"""Scoped early Campaign3 claim review, retaining original occurrence identities."""
from pathlib import Path
from fractions import Fraction as F
import json,hashlib,copy
P=Path('docs/planning');B=P/'campaign3-history-universe-rev1';O=P/'campaign3-history-ledger-agency-social-rev1';O.mkdir(exist_ok=True)
SOURCE='docs/planning/VERDICT_LEDGER.md'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def load(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def save(p,v):
 if p.exists():assert load(p)==v,p
 else:p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
specs=[(1716, 'LEARN', 'Gated lower-bound learning preserves informative evidence versus manufactured precision.', 'Fresh-prior repetition is not universal deduplication; established below-bound repetition still grows precision. Lattice failure retained; no general posterior law.', ['CAMPAIGN3_LEARN_QUALIFICATION.md']), (1739, 'EPI', 'Identical saturated evidence preserves character outputs despite different hidden overflow; encoding130 precedes independent learning140.', 'Leak controls are violations, not lawful competitors. Unknown belief can coexist with encoding; no memory necessity proof.', ['CAMPAIGN3_EPI_QUALIFICATION.md']), (1766, 'REASON', 'Motive/referent/role and one base die remain distinct; standing rescues weak existing reason, never zero base.', 'Aggregate versus pairwise and illegal extra dice are bounded contrasts, not general coverage/renaming law; both failed cohorts retained.', ['CAMPAIGN3_REASON_QUALIFICATION.md']), (1791, 'DECISION', 'Authoritative arbitration, presentation, intent, execution and observed history remain distinct.', 'Two-option reason-mass significance and balanced opaque marginal do not settle general grammar or control/uncertainty.', ['CAMPAIGN3_DECISION_QUALIFICATION.md']), (1811, 'COMMIT', 'Concrete obligations retire while earned standing and observer knowledge persist; new instance not reused identity.', 'Fixed+3, cancellation and two instances only; five verdicts close RO018, not broader lifecycle debt.', ['CAMPAIGN3_COMMIT_QUALIFICATION.md']), (1830, 'BODY', 'MeterBehindSensor and CachedEvidence match Mediated at sampled probes while epistemic boundary remains.', 'Component comparison over16 public sources is not new integrated public qualification, Need ontology or box retirement.', ['CAMPAIGN3_BODY_OWNERSHIP_QUALIFICATION.md']), (1849, 'BIO', 'Early seed variation affects later standing/intent; contradiction changes standing without rewriting historical meaning.', 'Refold equality needs complete history; DisplayOnly/HistoryOnly equal here. Preserve failed32-seed calibration and identity packaging correction. No public factory.', ['CAMPAIGN3_BIO_QUALIFICATION.md']), (1870, 'AGENCY', 'Intent survives obstruction; acquired causal belief follows observer evidence, with GroupedMean/LastClaim retained.', 'Initial later-nonrecipient occurrence leak fixed in0.2; intent80 corrected to70 in0.3. No general causal discovery, blame or coercion.', ['CAMPAIGN3_AGENCY_QUALIFICATION.md']), (1892, 'GOAL', 'Goal survives strategy gap and route replacement; admitted false attainment can fulfill, hidden attainment cannot.', 'One goal/two routes, not general planning or temporal conflict; controlled evidence and no random draws.', ['CAMPAIGN3_GOAL_STRATEGY_QUALIFICATION.md']), (1912, 'CONTROL', 'Load blocks inhibition without erasing habit/goal/belief; removing load restores inhibition and retiring goal exposes habit.', 'First cohort exceeded inherited one-reason grammar; successor typed contest preserves frozen HABIT. Not physiological fatigue or learned control.', ['CAMPAIGN3_CONTROL_QUALIFICATION.md']), (1934, 'INFER', 'New unique same-event causal reports revise belief without rewriting earlier intent; denied/duplicate/other-event reports do not.', 'Received claims only, not diagnosis, trust, source independence or explicit retraction; misleading correction possible.', ['CAMPAIGN3_INFERENCE_CORRECTION_QUALIFICATION.md']), (1954, 'REAPPRAISAL', 'Instructed frame140 changes later appraisal50 without changing belief or physical protection.', 'Ineffective/harmful conditions prevent forced relief; no actual strategy choice, downstream action or general regulation at this checkpoint.', ['CAMPAIGN3_REAPPRAISAL_QUALIFICATION.md']), (1971, 'RECOLLECT', 'Actual lost detail is reconstructed from learned routine without rewriting episode or learning from recall.', 'FragmentOnly/KeepDetail retained; TruthRestore/ReencodeGuess violate boundaries. Initial matrix pass followed by readonly build failure preserved.', ['CAMPAIGN3_RECOLLECTION_QUALIFICATION.md']), (1990, 'FAMILIAR', 'Surviving signature supports familiarity after detail loss without asserting identity; current observation cannot self-match.', 'ExactOnly retained, tied sources nonunique, missing not false. No reward/valence/action; branded-time build failure preserved.', ['CAMPAIGN3_FAMILIARITY_QUALIFICATION.md']), (2009, 'COMM', 'Own belief, chosen disclosure, produced assertion and recipient update require actual delivery. Honest mistake can be false.', 'Mean/Last retained; private copy and intent-as-delivery violate boundaries. Interrupted serial cohort preserved; no lying/trust/language claim.', ['CAMPAIGN3_COMMUNICATION_QUALIFICATION.md']), (2028, 'LYING', 'Lie defined by belief and purpose can accidentally be true; failed execution/denied receipt does not teach recipient.', 'Prior disclosure cohort separate; no general language/trust/mentalizing/moral identity. NoLearning separates available evidence from update.', ['CAMPAIGN3_LYING_QUALIFICATION.md']), (2048, 'DISPLAY', 'Private affect, assertion and unchosen cue differ; failure/access can independently affect channels.', 'Graded/Threshold retained. Initial calm comparison also changed control; corrected likelihood-only fixture and failures preserved. No general inhibition/fusion.', ['CAMPAIGN3_EMOTIONAL_DISPLAY_QUALIFICATION.md']), (2071, 'INTERPRET', 'Signal/context/interpretation/belief stay separate; later correction preserves earlier misunderstanding.', 'Two fixed conventions not learned language or joint communication. Negative/misleading alias counts once; IntentOracle illegal.', ['CAMPAIGN3_INTERPRETATION_QUALIFICATION.md']), (2093, 'ATTRIBUTED', 'Own belief, target belief and attributed belief differ; misleading reports alter chosen explanation.', 'Report-only contrast holds entire actual target state fixed. No factivity, trust or exposure-comprehension inference; stale-ID/read-bound/type failures preserved.', ['CAMPAIGN3_ATTRIBUTED_QUALIFICATION.md']), (2114, 'PERSONSTATE', 'Learned impression and current-intent estimate differ; target intent, execution and observer appraisal remain separate.', 'Stable target default is benchmark, not earned personality. First cohort appraised before intent;0.2 moves appraisal to consequence130 after intent70. No general personality/action claim.', ['CAMPAIGN3_PERSONSTATE_QUALIFICATION.md'])]

rows=[]
with (B/'units.jsonl').open(encoding='utf-8') as f:
 for line in f:
  u=json.loads(line)
  if u['source']!=SOURCE or not 1716<=u['location']['startLine']<=2135:continue
  assert u['location']['endLine']<=2135
  _,name,claim,limits,paths=max((s for s in specs if s[0]<=u['location']['startLine']),key=lambda s:s[0])
  rows.append(dict(occurrenceId=u['id'],location=u['location'],text=u['text'],claim=name,disposition=claim,limits=limits,evidence=paths))
raw=(B/'sources'/SOURCE).read_bytes();assert Path(SOURCE).read_bytes().startswith(raw)
lines=raw.decode('utf-8-sig').splitlines(keepends=True)
for r in rows:assert ''.join(lines[r['location']['startLine']-1:r['location']['endLine']])==r['text']
assert {n for r in rows for n in range(r['location']['startLine'],r['location']['endLine']+1)}=={n for n in range(1716,2136) if lines[n-1].strip()}
evidence=[]
for n in sorted({n for s in specs for n in s[4]}):
 p=P/n;evidence.append(dict(path=p.as_posix(),sha256=sha(p)))
v=dict(status='HQ011 AGENCY AND SOCIAL CLAIMS REVIEWED; WIDER AUDIT OPEN',source=dict(path=SOURCE,frozenSha256=sha(B/'sources'/SOURCE)),rows=rows,evidence=evidence,obligations=['RO-C3-001','RO-C3-005','RO-C3-006','RO-C3-007','RO-C3-008','RO-C3-009','RO-C3-010','RO-C3-011','RO-C3-012','RO-C3-013','RO-C3-014','RO-C3-015','RO-C3-016','RO-C3-017','RO-C3-018','RO-C3-019','RO-C3-020','RO-C3-021'],limits=['No fresh production simulation, test suite or build. Receipt bindings do not assert current source freshness for every old receipt.','Twenty reviewed claim groups retain independent public/component, law and historical correction scopes.'],nextGate='Ledger2136 onward: social attribution, dependence and biology.')
save(O/'review.json',v)
c=dict(status=v['status'],originalOccurrences=len(rows),claimGroups=len(specs),indexedWholeOccurrenceLinks=720+len(rows),freshBehavioralTests=0,reviewSha256=sha(O/'review.json'),checkerSha256=sha(__file__))
save(O/'check.json',c);print(json.dumps(c))
